def state(mem, step=8):
    reading = mem.get('_menu_navigation_feedback')
    return {'step': step, 'screen_kind': 'world_map', 'policy': mem,
            'menu_navigation_reading': {**reading, 'step': step} if reading else None}


def test_native_30_frame_cycle_keeps_the_same_six_castles_as_90_frames():
    proof = json.loads((FIX / 'ch11-recall-picker-tempo-evidence.json').read_text())
    slow, fast = proof['results']
    assert (slow['cycle_frames'], fast['cycle_frames']) == (90, 30)
    assert fast['route'] == slow['route']
    assert len(fast['route']) == 7 and fast['route'][0] == fast['route'][-1]
    assert sorted(row['castle'][0] for row in fast['route'][:-1]) == sorted(proof['owned'])
    path = FIX / proof['frame']['file']
    assert hashlib.sha256(path.read_bytes()).hexdigest() == proof['frame']['png_sha256']
    frame = read_png(path).resized()
    assert frame.digest() == proof['frame']['rgb_sha256']
    assert flow.world_cursor(frame, 11) == tuple(proof['frame']['cursor'])
    assert flow.world_flags(frame, 11) == proof['frame']['flags']


@pytest.mark.parametrize('name', ['g1190-ch11-recall-home', 'g1190-ch11-recall-gondal',
                                  'ch11-recall-picker-tempo-jansenia'])
def test_each_observed_castle_hop_gets_500ms_without_an_input_or_arrival_receipt(name):
    screen, frame = image(name)
    mem = memory()
    actions = flow.world_map_step(screen, mem, frame)
    observed = state(mem)
    before = deepcopy((observed, actions))
    assert actions == [pad('down')]
    assert entry.observation_interval_ms(observed, actions) == 500
    assert (observed, actions) == before
    assert not any(row['decision'] == 'camp_recall_requested' for row in mem['_records'])
    # A world-map picture alone does not identify the recall picker owner.
    assert menu_navigation_reading(screen) is None


def test_target_confirmation_clears_feedback_and_keeps_its_original_cadence():
    mem = memory()
    screen, frame = image('g1190-ch11-recall-home')
    flow.world_map_step(screen, mem, frame)
    assert mem.get('_menu_navigation_feedback')
    screen, frame = image('g1190-ch11-recall-maranma')
    actions = flow.world_map_step(screen, mem, frame)
    assert actions == [pad('a'), {'type': 'wait', 'ms': 700}, pad('a')]
    assert mem.get('_menu_navigation_feedback') is None
    assert entry.observation_interval_ms(state(mem), actions) == 1500


def test_an_incomplete_following_flag_read_drops_the_previous_fast_feedback(monkeypatch):
    screen, frame = image('g1190-ch11-recall-home')
    mem = memory()
    flow.world_map_step(screen, mem, frame)
    flags = flow.world_flags(frame, 11)
    flags.pop('ネペンテ')
    monkeypatch.setattr(flow, 'world_flags', lambda *_: flags)
    actions = flow.world_map_step(screen, mem, frame)
    # A non-cycle pick now holds proportionally to the remaining span (v1039);
    # the incomplete flag read still drops the previous fast feedback.
    assert actions == [pad('left', 56)]
    assert mem.get('_menu_navigation_feedback') is None
    assert entry.observation_interval_ms(state(mem), actions) == 1500


def test_the_existing_finite_fallback_never_keeps_fast_movement_feedback():
    screen, frame = image('g1190-ch11-recall-home')
    mem = memory()
    for _ in range(flow.PICKER_STILL_LIMIT):
        assert flow.world_map_step(screen, mem, frame) == [pad('down')]
        assert entry.observation_interval_ms(state(mem), [pad('down')]) == 500
    actions = flow.world_map_step(screen, mem, frame)
    assert actions == [pad('a'), {'type': 'wait', 'ms': 700}, pad('a')]
    assert mem.get('_menu_navigation_feedback') is None
    assert entry.observation_interval_ms(state(mem), actions) == 1500


