@pytest.mark.parametrize('change', ['old_step', 'other_kind', 'missing', 'other_menu', 'other_direction'])
def test_old_or_foreign_picker_reading_is_not_fast(change):
    screen, frame = image('g1190-ch11-recall-home')
    mem = memory()
    flow.world_map_step(screen, mem, frame)
    observed = state(mem)
    if change == 'old_step': observed['step'] += 1
    elif change == 'other_kind': observed['screen_kind'] = 'map'
    elif change == 'missing': observed['menu_navigation_reading'] = None
    elif change == 'other_menu': observed['menu_navigation_reading']['menu'] = 'survey'
    else: observed['menu_navigation_reading']['directions'] = ['up', 'down']
    assert entry.observation_interval_ms(observed, [pad('down')]) == 1500


def test_orchestrator_stamps_then_discards_the_transient_picker_evidence():
    _, frame = image('g1190-ch11-recall-home')
    def picker(screen, mem, source): return flow.world_map_step(screen, mem, source)
    with patch('docich.hanjuku_speedrun.hanjuku.flows.map_registration.step', return_value=None), \
         patch('docich.hanjuku_speedrun.hanjuku.flows.post_month_status.step', return_value=None), \
         patch('docich.hanjuku_speedrun.hanjuku.flows.arrival_status.step', return_value=None), \
         patch('docich.hanjuku_speedrun.hanjuku.flows.house.step', side_effect=picker):
        actions, observed = decide(frame, {'step': 17, 'policy': memory()})
    assert actions == [pad('down')]
    assert observed['menu_navigation_reading']['step'] == observed['step'] == 18
    assert '_menu_navigation_feedback' not in observed['policy']
    assert entry.observation_interval_ms(observed, actions) == 500
    following = read_png(FIX / 'g745-god-dialogue-8128.png')
    _, observed = decide(following, observed)
    assert observed['menu_navigation_reading'] is None
    assert entry.observation_interval_ms(observed, actions) == 1500


