def test_action_plan_keeps_native_pixels_current_feedback_and_original_input(tmp_path):
    screen, frame = image('g1190-ch11-recall-home')
    mem = memory()
    actions = flow.world_map_step(screen, mem, frame)
    observed = state(mem)
    identity = {'game': 'hanjuku-speedrun', 'runtime_id': 'test-runtime',
                'generation': 1, 'lease_id': 'test-lease'}
    with patch('docich.hanjuku_speedrun.hanjuku_scene.observe'), patch('docich.hanjuku_speedrun.hanjuku_progress.record'):
        entry.persist(tmp_path, observed, [], {'hanjuku': identity}, actions=actions,
                      frame_sha256=frame.digest(), frame=frame)
    rows = [json.loads(line) for line in (tmp_path / 'hanjuku_decisions.jsonl').read_text().splitlines()]
    plan = next(row for row in rows if row['event'] == 'action_plan')
    assert plan['planned_actions'] == actions == [pad('down')]
    assert plan['observation_interval_ms'] == 500
    assert plan['menu_navigation_feedback'] == observed['menu_navigation_reading']
    assert read_png(tmp_path / 'hanjuku_frames' / plan['snapshot']).digest() == frame.digest()
